-- Additive draft tools only; no final average, rejection or productive CAT barrier.
create table public.review_templates(id text primary key,stage integer not null check(stage in(1,2)),kind text not null check(kind in('rubric','administrative')),criteria jsonb not null);
create table public.call_review_templates(call_id uuid references public.calls(id),stage integer not null,kind text not null,template_id text not null references public.review_templates(id),primary key(call_id,stage,kind));
create table public.review_working_drafts(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id),version_id uuid not null references public.application_versions(id),reviewer_id uuid not null references public.profiles(id),template_id text not null references public.review_templates(id),kind text not null,answers jsonb not null,notes text not null default '',revision integer not null default 1,updated_at timestamptz not null default now(),unique(version_id,reviewer_id,kind));
create table public.review_draft_history(id bigint generated always as identity primary key,draft_id uuid not null references public.review_working_drafts(id),application_id uuid not null references public.applications(id),reviewer_id uuid not null references public.profiles(id),revision integer not null,answers jsonb not null,notes text not null,created_at timestamptz not null default now());
insert into public.review_templates(id,stage,kind,criteria) values ('manual-glf-2025-v1-rubric-1',1,'rubric','[{"id": "1.1", "group": "Pertinencia del proyecto", "text": "Pertinencia del proyecto para abordar las prioridades nacionales y las prioridades del Fondo", "max": 5}, {"id": "1.2", "group": "Pertinencia del proyecto", "text": "¿La propuesta refleja y complementa con exactitud la situación actual de las actividades en el ámbito propuesto y no duplica otras iniciativas?", "max": 5}, {"id": "2.1", "group": "Eficacia y viabilidad del proyecto", "text": "¿Está claramente identificado el problema o la cuestión que abordará el proyecto?", "max": 5}, {"id": "2.2", "group": "Eficacia y viabilidad del proyecto", "text": "¿Es el proyecto realista y es probable que tenga los resultados/impactos esperados en el plazo previsto?", "max": 5}, {"id": "2.3", "group": "Eficacia y viabilidad del proyecto", "text": "¿Son las actividades propuestas prácticas y coherentes en relación con los objetivos, la finalidad y los resultados esperados?", "max": 5}, {"id": "2.4", "group": "Eficacia y viabilidad del proyecto", "text": "¿Hay una buena participación de las partes interesadas y los socios?", "max": 5}, {"id": "3.1", "group": "Sostenibilidad del proyecto", "text": "¿Es probable que el proyecto sea sostenible?", "max": 5}, {"id": "3.2", "group": "Sostenibilidad del proyecto", "text": "¿Existe la posibilidad de replicarlo o de ampliarlo?", "max": 5}, {"id": "4.1", "group": "Presupuesto", "text": "¿El presupuesto (incluida la cofinanciación) es adecuado para las actividades propuestas?", "max": 5}, {"id": "4.2", "group": "Presupuesto", "text": "¿El desglose del presupuesto es claro y realista?", "max": 5}]'::jsonb);
insert into public.review_templates(id,stage,kind,criteria) values ('manual-glf-2025-v1-administrative-1',1,'administrative','[{"id": "eligibility", "group": "Admisibilidad", "text": "¿Es elegible el solicitante y la propuesta en esta ronda?", "sourceItem": 1}, {"id": "category", "group": "Admisibilidad", "text": "¿Coincide la propuesta con las categorías de subvención del GLF?", "sourceItem": 2}, {"id": "screening", "group": "Admisibilidad", "text": "¿El solicitante realizó el Examen Ambiental y Social y las actividades descritas en su nota conceptual no son parte de la Lista de exclusiones del GLF?", "sourceItem": 3}, {"id": "deadline", "group": "Presentación completa", "text": "¿Se ha presentado la nota conceptual antes de la fecha límite?", "sourceItem": 3}, {"id": "experience", "group": "Presentación completa", "text": "¿Se incluye la información de referencia requerida (si se trata de una organización) o el CV (si se trata de una persona)?", "sourceItem": 4}, {"id": "budget", "group": "Presentación completa", "text": "¿Se incluye el presupuesto detallado?", "sourceItem": 5}, {"id": "cofinance", "group": "Presentación completa", "text": "¿Se proporciona una cofinanciación indicativa a un nivel que se ajuste a la solicitud de subvención del Fondo (grandes proyectos); hay al menos alguna cofinanciación (pequeños proyectos)?", "sourceItem": 6}, {"id": "format", "group": "Formato del proyecto", "text": "¿Se presenta la nota conceptual en el formato correcto (utilizando la plantilla facilitada)?", "sourceItem": 7}]'::jsonb);
insert into public.review_templates(id,stage,kind,criteria) values ('manual-glf-2025-v1-rubric-2',2,'rubric','[{"id": "1.1", "group": "Capacidad de ejecución", "text": "¿Capacidad de la organización o del individuo para ejecutar el proyecto propuesto?", "max": 5}, {"id": "1.2", "group": "Capacidad de ejecución", "text": "¿Experiencia de la organización o del individuo en proyectos similares?", "max": 5}, {"id": "2.1", "group": "Objetivos y actividades del proyecto", "text": "¿Está claramente definida la lógica del proyecto - es probable que las actividades alcancen los resultados y el objetivo?", "max": 5}, {"id": "2.2", "group": "Objetivos y actividades del proyecto", "text": "¿Están claramente definidas las actividades del proyecto y son realizables en el plazo establecido?", "max": 5}, {"id": "2.3", "group": "Objetivos y actividades del proyecto", "text": "¿Se han identificado los riesgos y se han mitigado eficazmente?", "max": 5}, {"id": "2.4", "group": "Objetivos y actividades del proyecto", "text": "¿Están claramente definidos los indicadores y los medios de seguimiento de los avances con respecto a los indicadores?", "max": 5}, {"id": "2.5", "group": "Objetivos y actividades del proyecto", "text": "¿Están claramente definidos los medios por los que se mantendrán y reproducirán las intervenciones del proyecto?", "max": 5}, {"id": "3.1", "group": "Presupuesto", "text": "¿Están claramente identificadas y son realistas las contribuciones del proponente y de los cofinanciadores?", "max": 5}, {"id": "3.2", "group": "Presupuesto", "text": "¿Es claro y realista el desglose del presupuesto por actividades?", "max": 5}, {"id": "3.3", "group": "Presupuesto", "text": "¿Es apropiado el desglose del presupuesto por categorías y es probable que sea rentable?", "max": 5}, {"id": "4.1", "group": "PGAS y salvaguardas", "text": "¿Son claros y realistas los instrumentos de salvaguardas y el Plan de Gestión Ambiental y Social (PGAS)?", "max": 5}]'::jsonb);
insert into public.review_templates(id,stage,kind,criteria) values ('manual-glf-2025-v1-administrative-2',2,'administrative','[{"id": "eligibility", "group": "Elegibilidad", "text": "Elegibilidad (comprobada en la fase de concepción)", "sourceItem": "Si"}, {"id": "deadline", "group": "Presentación completa", "text": "¿Se ha presentado la propuesta completa durante el plazo establecido?", "sourceItem": 1}, {"id": "instruments", "group": "Presentación completa", "text": "¿Se incluyen las versiones preliminares requeridas del PGAS y de las salvaguardas (anexos)?", "sourceItem": 2}, {"id": "experience", "group": "Presentación completa", "text": "¿Se incluye la información de referencia requerida (si se trata de una organización) o el CV (si se trata de una persona) (anexo)?", "sourceItem": 3}, {"id": "budget", "group": "Presentación completa", "text": "¿Se incluye el presupuesto desglosado?", "sourceItem": 3}, {"id": "cofinance", "group": "Presentación completa", "text": "¿Se proporciona una cofinanciación indicativa a un nivel que se ajuste a la solicitud de subvención del Fondo?", "sourceItem": 4}, {"id": "format", "group": "Formato del proyecto", "text": "¿Se presenta la propuesta completa en el formato correcto (utilizando la plantilla facilitada)?", "sourceItem": 5}]'::jsonb);
alter table public.review_templates enable row level security;
alter table public.call_review_templates enable row level security;
alter table public.review_working_drafts enable row level security;
alter table public.review_draft_history enable row level security;
revoke all on public.review_templates,public.call_review_templates,public.review_working_drafts,public.review_draft_history from public,anon,authenticated;
grant select on public.review_templates,public.call_review_templates,public.review_working_drafts,public.review_draft_history to authenticated;
create policy review_templates_read on public.review_templates for select to authenticated using(private.current_role() in('committee_member','grants_manager','project_coordinator','administrator'));
create policy call_review_templates_read on public.call_review_templates for select to authenticated using(private.current_role() in('committee_member','grants_manager','project_coordinator','administrator'));
create policy working_review_read on public.review_working_drafts for select to authenticated using((reviewer_id=auth.uid() or private.current_role()='administrator') and private.current_role() in('committee_member','grants_manager','project_coordinator','administrator') and private.can_read_application(application_id));
create policy working_history_read on public.review_draft_history for select to authenticated using((reviewer_id=auth.uid() or private.current_role()='administrator') and private.current_role() in('committee_member','grants_manager','project_coordinator','administrator') and private.can_read_application(application_id));
create function public.save_working_review(app_id uuid,submitted_version uuid,review_kind text,expected_revision integer,values_json jsonb,observation text) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.applications; v public.application_versions; t public.review_templates; d public.review_working_drafts; key text; val jsonb;
begin
 if expected_revision is null or expected_revision<0 then raise exception 'GLF_VERSION_CONFLICT'; end if;
 if review_kind='rubric' then perform private.require_role(array['committee_member','administrator']::public.app_role[]);
 elsif review_kind='administrative' then perform private.require_role(array['grants_manager','project_coordinator','administrator']::public.app_role[]);
 else raise exception 'GLF_INVALID_REVIEW_KIND'; end if;
 select * into a from public.applications where id=app_id for update;
 if not found or a.submitted_at is null or not private.can_read_application(app_id) or a.status not in('submitted','under_review','phase2_submitted') or a.correction_deadline>now() then raise exception 'GLF_REVIEW_STATE'; end if;
 select * into v from public.application_versions where application_id=app_id order by revision desc limit 1;
 if v.id is distinct from submitted_version then raise exception 'GLF_VERSION_CONFLICT'; end if;
 select rt.* into t from public.call_review_templates ct join public.review_templates rt on rt.id=ct.template_id where ct.call_id=a.call_id and ct.stage=v.stage and ct.kind=review_kind;
 if not found then
 select * into t from public.review_templates where stage=v.stage and kind=review_kind order by id desc limit 1;
 insert into public.call_review_templates values(a.call_id,v.stage,review_kind,t.id) on conflict do nothing;
 select rt.* into t from public.call_review_templates ct join public.review_templates rt on rt.id=ct.template_id where ct.call_id=a.call_id and ct.stage=v.stage and ct.kind=review_kind;
 end if;
 if jsonb_typeof(values_json) is distinct from 'object' or length(values_json::text)>20000 or length(coalesce(observation,''))>5000 then raise exception 'GLF_INVALID_REVIEW'; end if;
 for key,val in select * from jsonb_each(values_json) loop
 if not exists(select 1 from jsonb_array_elements(t.criteria) c where c->>'id'=key) then raise exception 'GLF_INVALID_REVIEW_CRITERION'; end if;
 if review_kind='rubric' then
 if val<>'null'::jsonb and (jsonb_typeof(val)<>'number' or val::text !~ '^[1-5]$') then raise exception 'GLF_INVALID_REVIEW_SCORE'; end if;
 elsif val<>'null'::jsonb and val#>>'{}' not in('yes','no','pending','not_applicable') then raise exception 'GLF_INVALID_CHECKLIST'; end if;
 end loop;
 select * into d from public.review_working_drafts where version_id=v.id and reviewer_id=auth.uid() and kind=review_kind for update;
 if found then
 if d.revision<>expected_revision then raise exception 'GLF_VERSION_CONFLICT'; end if;
 update public.review_working_drafts set answers=values_json,notes=coalesce(observation,''),revision=revision+1,updated_at=now() where id=d.id returning * into d;
 else
 if expected_revision<>0 then raise exception 'GLF_VERSION_CONFLICT'; end if;
 insert into public.review_working_drafts(application_id,version_id,reviewer_id,template_id,kind,answers,notes) values(a.id,v.id,auth.uid(),t.id,review_kind,values_json,coalesce(observation,'')) returning * into d;
 end if;
 insert into public.review_draft_history(draft_id,application_id,reviewer_id,revision,answers,notes) values(d.id,a.id,auth.uid(),d.revision,d.answers,d.notes);
 return jsonb_build_object('id',d.id,'revision',d.revision,'template_id',d.template_id);
end $$;
revoke all on function public.save_working_review(uuid,uuid,text,integer,jsonb,text) from public,anon;
grant execute on function public.save_working_review(uuid,uuid,text,integer,jsonb,text) to authenticated;
